cd /private/tmp/claude/claude-502/-Users-kenneth--claude-spares-spare-Nzsulp/27aeb673-3e7e-4b6a-bee5-c6666cf59545/scratchpad/tr; python3 - <<'EOF'
import json,re
for l in "ja ko vi zh_CN zh_TW".split():
    d=json.load(open(l+".json",encoding="utf-8"))
    bad=[]
    for sec in d:
        for k,v in d[sec].items():
            if not v: bad.append(("empty",k))
            ph=lambda s:sorted(set(re.findall(r'\{(\w+)[,}]',s)))
            if ph(k)!=ph(v): bad.append(("ph",k))
            if sorted(re.findall(r'</?\d+>|%1%|#|http://127.0.0.1:1234|32k',k))!=sorted(re.findall(r'</?\d+>|%1%|#|http://127.0.0.1:1234|32k',v)) and 'plural' not in k: bad.append(("tok",k))
            if 'plural' in k and '#' not in v: bad.append(("hash",k))
    print(l,"ok" if not bad else bad)
EOF

